    const k = 9, fs = 18, m = met(BF, 400, fs), x = 330, w = 1150, top = 300;
    const lhv = t < 15.2 ? 28 : keyed([[15.2, 26.1], [16.4, 26.1], [17.4, 28]], t);
    const lh = t < 15.2 ? 28 : lhv, b = baseOf(0, lh, m), ca = (lh - (m.asc + m.desc)) / 2, Y = v => top + v * k;
