    RAMP.forEach((r, i) => { if (i <= idx) s += `<circle cx="${f1(X(r[4]))}" cy="${f1(Y(r[5] / r[4]))}" r="${i === idx ? 9 : 5}" class="dot"/>` + (i === idx ? T(X(r[4]) + 14, Y(r[5] / r[4]) - 12, r[0], 'dt') : ''); });
    s += T(gx, gy - 16, 'LH ÷ FS', 'dts');
